# Search for OLMo 1v2 bootstrap CI near [0.496, 0.519]
def find_ci(d, target_lower, target_upper, tol=0.005, path=''):
    results = []
    if isinstance(d, dict):
        if 'ci_lower' in d and 'ci_upper' in d:
            cl = d['ci_lower']
            cu = d['ci_upper']
            if isinstance(cl, (int,float)) and isinstance(cu, (int,float)):
                if abs(cl - target_lower) < tol and abs(cu - target_upper) < tol:
                    results.append((path, cl, cu))
        if 'ci' in d and isinstance(d['ci'], list) and len(d['ci']) == 2:
            cl, cu = d['ci']
            if abs(cl - target_lower) < tol and abs(cu - target_upper) < tol:
                results.append((path+'[ci]', cl, cu))
