            new_path = f'{path}.{k}' if path else k
            if isinstance(v, (dict, list)):
                results.extend(find_ci(v, target_lower, target_upper, tol, new_path))
    elif isinstance(d, list):
        for i, v in enumerate(d):
            results.extend(find_ci(v, target_lower, target_upper, tol, f'{path}[{i}]'))
    return results

